</style></head><body><div id="viewport"><main id="stage"><div class="dots"><i></i><i></i><i></i><i></i><i></i></div><header class="head"><div><h1>MCU 是什么：CPU、MCU、SoC 三层关系</h1><div class="sub">单芯片集成 · CPU + 存储 + 外设 · 最小系统</div></div></header><section class="panel"><svg viewBox="0 0 980 410" class="svg">
<!-- step1: CPU 单核 -->
<g data-step="1">
<rect class="chip" x="60" y="160" width="180" height="100" rx="20"/>
<text x="150" y="200" class="chipText" font-size="28">CPU</text>
<text x="150" y="226" class="chipText" font-size="14">运算 · 控制</text>
<text x="150" y="246" class="chipText" font-size="14">寄存器组 · ALU</text>
<text x="150" y="295" class="layerSub">需外接 RAM/Flash 才能工作</text>
</g>

<!-- step2: MCU 集成 -->
<g data-step="2">
<rect class="layer" x="280" y="80" width="380" height="260" rx="22"/>
<text x="470" y="68" class="layerText">MCU 单芯片集成</text>
<rect class="chip" x="305" y="115" width="100" height="72" rx="14"/>
<text x="355" y="148" class="chipText" font-size="18">CPU</text>
<text x="355" y="170" class="chipText" font-size="13">Cortex-M3</text>
<rect class="layer warn" x="420" y="115" width="100" height="72" rx="14"/>
<text x="470" y="148" class="layerText" font-size="18" fill="#B45309">RAM</text>
<text x="470" y="172" class="layerSub">20KB</text>
<rect class="layer warn" x="535" y="115" width="100" height="72" rx="14"/>
<text x="585" y="148" class="layerText" font-size="18" fill="#B45309">Flash</text>
<text x="585" y="172" class="layerSub">64KB</text>
<rect class="layer success" x="305" y="200" width="100" height="60" rx="14"/>
<text x="355" y="234" class="layerText" font-size="16">GPIO</text>
<rect class="layer success" x="420" y="200" width="100" height="60" rx="14"/>
<text x="470" y="234" class="layerText" font-size="16">UART</text>
<rect class="layer success" x="535" y="200" width="100" height="60" rx="14"/>
<text x="585" y="234" class="layerText" font-size="16">Timer</text>
<rect class="layer success" x="305" y="270" width="100" height="50" rx="14"/>
<text x="355" y="300" class="layerText" font-size="16">ADC</text>
<rect class="layer success" x="420" y="270" width="100" height="50" rx="14"/>
<text x="470" y="300" class="layerText" font-size="16">SPI/I2C</text>
<rect class="layer success" x="535" y="270" width="100" height="50" rx="14"/>
<text x="585" y="300" class="layerText" font-size="16">PWM</text>
</g>

<!-- step3: 上电独立工作 -->
<g data-step="3">
<circle cx="700" cy="180" r="30" fill="#FFF8EC" stroke="#D97706" stroke-width="3"/>
<text x="700" y="187" class="layerText" font-size="18" fill="#B45309">3.3V</text>
<text x="700" y="232" class="layerSub">VCC</text>
<line x1="660" y1="180" x2="700" y2="180" stroke="#D97706" stroke-width="3"/>
<circle cx="780" cy="180" r="22" fill="#DCFCE7" stroke="#10915A" stroke-width="3"/>
<text x="780" y="186" class="layerText" font-size="14" fill="#0A5132">8MHz</text>
<text x="780" y="222" class="layerSub">晶振</text>
</g>

<!-- step4: SoC 横向对比 -->
<g data-step="4">
<rect class="layer" x="60" y="345" width="430" height="55" rx="14" stroke="#0E7C4A"/>
<text x="78" y="377" class="layerText" font-size="18" text-anchor="start">MCU · 单核 + 外设 · 控制为主</text>
<rect class="layer warn" x="510" y="345" width="430" height="55" rx="14"/>
<text x="528" y="377" class="layerText" font-size="18" text-anchor="start" fill="#B45309">SoC · 多核 + DSP + GPU + 射频</text>
</g>

