<g data-step="5">
<rect class="layer success breath" x="700" y="240" width="240" height="100" rx="22"/>
<text x="820" y="278" class="layerText" font-size="22" fill="#0A5132">STM32F103</text>
<text x="820" y="304" class="layerSub">32 位 · 72MHz</text>
<text x="820" y="324" class="layerSub">本课主芯片</text>
</g>
</svg></section><aside class="side"><div class="formulaBox"><h2>核心定义</h2><p>MCU = CPU + RAM + Flash + 外设</p></div><ol><li data-k="0"><b>1</b><span>CPU 只是运算与控制核心，需要外接存储与外设才能跑程序。</span></li>
<li data-k="1"><b>2</b><span>MCU 把 CPU 内核、RAM、Flash、定时器、串口等集成到同一颗芯片。</span></li>
<li data-k="2"><b>3</b><span>一颗 MCU 通常上电、复位、时钟齐备即可独立工作。</span></li>
<li data-k="3"><b>4</b><span>SoC 比 MCU 更大，集成 DSP、GPU、射频、多核，常用于手机、网关。</span></li>
<li data-k="4"><b>5</b><span>本课聚焦 STM32F103，属于 32 位通用 MCU，主频 72MHz。</span></li></ol></aside><section class="metrics"><div class="metric"><strong>CPU</strong><span>运算核心</span></div>
<div class="metric"><strong>MCU</strong><span>CPU+外设</span></div>
<div class="metric"><strong>SoC</strong><span>系统级集成</span></div>
<div class="metric"><strong>72MHz</strong><span>STM32F103</span></div></section><footer class="caption"><div id="cn"></div></footer></main></div><script>
/* —— 受控显示器：所有 step 推进由 parent 通过 dgb-step 驱动 —— */
const steps=["CPU 只是运算与控制核心，需要外接存储与外设才能跑程序。", "MCU 把 CPU 内核、RAM、Flash、定时器、串口等集成到同一颗芯片。", "一颗 MCU 通常上电、复位、时钟齐备即可独立工作。", "SoC 比 MCU 更大，集成 DSP、GPU、射频、多核，常用于手机、网关。", "本课聚焦 STM32F103，属于 32 位通用 MCU，主频 72MHz。"];
const total=steps.length;
function measureContentH(scale){try{let maxBottom=0;const sr=stage.getBoundingClientRect();const all=stage.querySelectorAll('*');for(const el of all){const cs=getComputedStyle(el);if(cs.display==='none'||cs.visibility==='hidden')continue;const r=el.getBoundingClientRect();const bottom=r.bottom-sr.top;if(bottom>maxBottom)maxBottom=bottom;}const rawH=Math.ceil(maxBottom/Math.max(scale,.0001))+24;return Math.min(1080,Math.max(220,rawH));}catch(e){return 1080}}function fit(){const s=Math.max(.18,innerWidth/1920);stage.style.transform=`scale(${s})`;stage.style.transformOrigin='top left';stage.style.left='0px';stage.style.top='0px';const ch=measureContentH(s);parent.postMessage({type:'dgb-iframe-height',height:Math.ceil(ch*s)},'*')}
addEventListener('resize',fit);
let step=0;
function render(i){
 step=Math.max(0,Math.min(total-1,i));
 document.querySelectorAll('li[data-k]').forEach(el=>{const k=Number(el.dataset.k);el.classList.toggle('active',k===step);el.classList.toggle('done',k<step)});
 document.querySelectorAll('.dots i').forEach((el,k)=>{el.classList.toggle('active',k===step);el.classList.toggle('done',k<step)});
 document.querySelectorAll('[data-step]').forEach(el=>{const k=Number(el.dataset.step)-1;el.classList.toggle('show',k<=step);el.classList.toggle('current',k===step)});
 document.querySelectorAll('.metric').forEach((el,k)=>el.classList.toggle('hl',k===step));
 cn.textContent=steps[step]||'';
 parent.postMessage({type:'dgb-step-change',step,total},'*');setTimeout(fit,40)
}
addEventListener('message',e=>{
 const d=e.data||{};
 if(d.type==='dgb-step'){render(d.step|0);return}
 if(d.type==='dgb-reset'||d.type==='dgb-anim-finalize'){render(0);return}
 if(d.type==='SET_WIDGET_STATE'&&d.state)Object.entries(d.state).forEach(([k,v])=>{const el=document.getElementById(k);if(el)el.textContent=v});
 if(d.type==='HIGHLIGHT_ELEMENT'){const el=document.querySelector(d.target);if(el){el.classList.add('current');setTimeout(()=>el.classList.remove('current'),2400)}}
 if(d.type==='ANNOTATE_ELEMENT'){cn.textContent=d.text||cn.textContent}
});
/* visibilitychange / pagehide 仅作清场，不再驱动 RAF */
document.addEventListener('visibilitychange',()=>{});
addEventListener('pagehide',()=>{});
fit();
parent.postMessage({type:'dgb-steps-total',total},'*');
render(0);
</script></body></html>

