<circle cx="290" cy="180" r="24" class="tnode"/>
<text x="290" y="186" class="tlabel" font-size="14">8</text>
<text x="290" y="135" class="tlabel">1980</text>
<text x="290" y="225" class="tsub">Intel 8051</text>
<text x="290" y="245" class="tsub">工业标配</text>
</g>

