#include "stm32f1xx_hal.h"

/* HAL库将寄存器操作封装为函数调用 */
void led_stm32(void) {
    /* HAL_GPIO_TogglePin 内部操作BSRR寄存器 */
    HAL_GPIO_TogglePin(GPIOC, GPIO_PIN_13);
}

/* 直接寄存器操作（性能最高，可读性低）*/
void led_register(void) {
    /* 通过BSRR（bit set/reset register）原子操作 */
    GPIOC->BSRR = GPIO_PIN_13;  /* 置高 */
